// Kiểm tra lệnh và trạng thái bài trong lịch đăng
const cmd = $('Khi được gọi').first().json;
// /choduyet: danh sách bài Chờ duyệt (còn thiếu gì) + bài đã duyệt chờ đăng
if (cmd.action === 'list') {
  const all = $('Đọc lịch đăng').all().map(i => i.json);
  const h = (s) => { let x = 5381; for (const ch of String(s || '')) x = ((x * 33) ^ ch.charCodeAt(0)) >>> 0; return x.toString(36); };
  const ten = (r) => { const t = String(r['Tiêu đề'] || '').trim() || String(r['Nội dung'] || '').split('\n')[0]; return t.length > 55 ? t.slice(0, 55) + '…' : t; };
  const tinhTrang = (r) => {
    const anh = String(r['Link ảnh'] || '').trim(), bia = String(r['Ảnh bìa OA'] || '').trim();
    const src = (bia.match(/#src=([a-z0-9]+)/) || [])[1];
    const thieu = [];
    if (!anh) thieu.push('❌ chưa ảnh bài');
    if (!bia) thieu.push('❌ chưa ảnh bìa');
    else if (src && anh && src !== h(anh)) thieu.push('⚠️ ảnh bìa lệch ảnh bài');
    return thieu.length ? thieu.join(', ') : '✅ đủ ảnh → /duyet ' + r['ID'];
  };
  const cho = all.filter(r => String(r['Trạng thái'] || '').trim() === 'Chờ duyệt');
  const dang = all.filter(r => String(r['Trạng thái'] || '').trim() === 'Chờ đăng');
  const L = [];
  L.push(cho.length ? `📋 BÀI CHỜ DUYỆT (${cho.length}):` : '📋 Không có bài nào đang chờ duyệt.');
  cho.slice(-15).forEach(r => L.push(`#${r['ID']} ${ten(r)}\n   ${tinhTrang(r)}`));
  if (cho.length > 15) L.push(`(… còn ${cho.length - 15} bài cũ hơn)`);
  L.push('');
  L.push(dang.length ? `📅 ĐÃ DUYỆT, CHỜ ĐĂNG (${dang.length}) – mỗi tối 19:30 đăng 1 bài theo thứ tự:` : '📅 Chưa có bài nào đã duyệt chờ đăng.');
  dang.slice(0, 10).forEach((r, i) => L.push(`#${r['ID']} ${ten(r)}${r['Thời gian đăng'] ? ' – hẹn ' + r['Thời gian đăng'] : i === 0 ? ' – đăng lượt tới' : ''}`));
  L.push('');
  const ck = all.filter(r => String(r['Trạng thái'] || '').trim() === 'Chờ công khai');
  if (ck.length) { L.push(`👀 ĐÃ XEM TRƯỚC, HẸN CÔNG KHAI (${ck.length}):`); ck.slice(0, 10).forEach(r => L.push(`#${r['ID']} ${ten(r)} – ${r['Thời gian đăng'] || ''}`)); L.push(''); }
  L.push('👀 Xem bài: /xem <số> chu <số bản> | 🖼️ /xemanh <số> | 🔍 /xemtruoc <số> | 🗂️ /lichsu <số> | 🗑️ /bo <số>');
  return [{ json: { ok: false, reply: L.join('\n').slice(0, 1990) } }];
}
// ----- Hẹn giờ đăng: "20:15", "20h", "20h15", "9:00 13/11", "8h mai"; "huy" = bỏ hẹn giờ -----
const ZONE = 'Asia/Ho_Chi_Minh';
function docGio(s) {
  s = String(s || '').toLowerCase().trim();
  if (!s) return null;
  if (/^(huy|hủy|xoa|xóa|bo|bỏ)$/.test(s)) return '';
  const m = s.match(/(\d{1,2})\s*(?:h|giờ|g|:)\s*(\d{1,2})?/);
  if (!m) return 'loi';
  const H = +m[1], M = +(m[2] || 0);
  if (H > 23 || M > 59) return 'loi';
  const now = DateTime.now().setZone(ZONE);
  const dm = s.match(/(\d{1,2})\s*[\/\-.]\s*(\d{1,2})(?:\s*[\/\-.]\s*(\d{2,4}))?/);
  let d = now;
  if (dm) {
    const y = dm[3] ? (dm[3].length === 2 ? 2000 + +dm[3] : +dm[3]) : now.year;
    d = DateTime.fromObject({ year: y, month: +dm[2], day: +dm[1] }, { zone: ZONE });
    if (!d.isValid) return 'loi';
  } else if (/mai/.test(s)) d = now.plus({ days: 1 });
  let t = d.set({ hour: H, minute: M, second: 0, millisecond: 0 });
  if (!dm && !/mai/.test(s) && t <= now.plus({ minutes: 1 })) t = t.plus({ days: 1 });
  if (t <= now) return 'qua';
  return t.toFormat('d/M/yyyy H:mm');
}
const GIO_HD = 'Ví dụ: "20:15" (hôm nay, qua rồi thì mai), "20h", "9h30 mai", "8:00 15/11". Gõ "huy" để bỏ hẹn giờ (đăng lúc 19:30).';
const id = Number(cmd.id);
const rows = $('Đọc lịch đăng').all().map(i => i.json);
const row = rows.find(r => Number(r['ID']) === id);
const now = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM/yyyy HH:mm');
const duyet = cmd.action === 'duyet';
if (!row) return [{ json: { ok: false, reply: `❌ Không tìm thấy bài #${cmd.id} trong lịch đăng.` } }];
const st = String(row['Trạng thái'] || '').trim();
if (cmd.action === 'hengio') {
  if (!['Chờ duyệt', 'Chờ đăng'].includes(st)) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} đang "${st || 'trống'}" nên không hẹn giờ được.` } }];
  const g = docGio(cmd.gio);
  if (g === null || g === 'loi') return [{ json: { ok: false, reply: `ℹ️ Chưa hiểu giờ đăng "${cmd.gio || ''}".\n⏰ Gõ: /hengio ${id} <giờ> [ngày]\n${GIO_HD}` } }];
  if (g === 'qua') return [{ json: { ok: false, reply: `ℹ️ Giờ "${cmd.gio}" đã qua rồi, chọn giờ khác.` } }];
  const now2 = DateTime.now().setZone(ZONE).toFormat('dd/MM/yyyy HH:mm');
  return [{ json: { ok: true, update: { 'ID': String(id), 'Trạng thái': st, 'Thời gian đăng': g, 'Ghi chú': `${row['Ghi chú'] || ''} | Hẹn giờ qua Zalo ${now2}: ${g || 'bỏ hẹn giờ'}`.replace(/^ \| /, '') },
    reply: g ? `⏰ Bài #${id} sẽ đăng lúc ${g}${st === 'Chờ duyệt' ? '\n(Bài vẫn Chờ duyệt: nhớ /duyet ' + id + ' trước giờ đó, chưa duyệt thì không đăng)' : ''}.` : `⏰ Đã bỏ hẹn giờ bài #${id}, bài sẽ đăng theo lượt lúc 19:30.` } }];
}
if (st !== 'Chờ duyệt' && !(!duyet && ['Chờ đăng', 'Chờ công khai'].includes(st))) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} đang ở trạng thái "${st || 'trống'}", không phải "Chờ duyệt" nên không đổi gì.` } }];
// /duyet là bước chốt cuối: phải có ảnh bìa Zalo OA và ảnh bìa phải làm từ đúng ảnh vuông hiện tại
if (duyet) {
  const h = (s) => { let h = 5381; for (const ch of String(s || '')) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0; return h.toString(36); };
  if (!String(row['Link ảnh'] || '').trim()) return [{ json: { ok: false, reply: `⚠️ Bài #${id} chưa có ảnh bài nên chưa duyệt.\n📎 Gửi ảnh vuông vào nhóm, ghi chú: /dunganh ${id}  (hoặc gõ /anh ${id} để AI vẽ)` } }];
  const bia = String(row['Ảnh bìa OA'] || '').trim();
  if (!bia) return [{ json: { ok: false, reply: `⚠️ Bài #${id} chưa có ảnh bìa Zalo OA nên chưa duyệt.\n🖌️ Gõ /anhbia ${id} để tạo ảnh bìa, xem ưng rồi /duyet ${id} lại.` } }];
  const src = (bia.match(/#src=([a-z0-9]+)/) || [])[1];
  if (src && src !== h(row['Link ảnh'])) return [{ json: { ok: false, reply: `⚠️ Ảnh bài #${id} đã đổi sau khi tạo ảnh bìa nên ảnh bìa không còn khớp, chưa duyệt.\n🖌️ Gõ /anhbia ${id} để tạo lại (hoặc /hoantac ${id} bia về ảnh bìa đúng), rồi /duyet ${id}.` } }];
}
let gioMoi = null;
if (duyet && cmd.gio) {
  gioMoi = docGio(cmd.gio);
  if (gioMoi === 'loi') return [{ json: { ok: false, reply: `ℹ️ Chưa hiểu giờ đăng "${cmd.gio}" nên chưa duyệt.\n${GIO_HD}` } }];
  if (gioMoi === 'qua') return [{ json: { ok: false, reply: `ℹ️ Giờ "${cmd.gio}" đã qua rồi nên chưa duyệt, chọn giờ khác.` } }];
}
const gioDang = gioMoi !== null ? gioMoi : String(row['Thời gian đăng'] || '').trim();
const note = `${row['Ghi chú'] || ''} | ${duyet ? 'Duyệt' : 'Bỏ'} qua Zalo ${now}`.replace(/^ \| /, '');
return [{ json: {
  ok: true,
  update: { 'ID': String(id), 'Trạng thái': duyet ? 'Chờ đăng' : 'Đã bỏ', 'Thời gian đăng': duyet ? gioDang : String(row['Thời gian đăng'] || ''), 'Ghi chú': note },
  reply: duyet
    ? `✅ Đã duyệt bài #${id}. Bài chuyển sang "Chờ đăng"${gioDang ? ', sẽ đăng lúc ' + gioDang : ' và sẽ tự đăng lúc 19:30 (mỗi ngày đăng 1 bài theo thứ tự duyệt)'}.\n⏰ Đổi giờ: /hengio ${id} <giờ>.`
    : `🗑️ Đã bỏ bài #${id}. Bài sẽ không được đăng${st === 'Chờ đăng' ? ' (đã gỡ khỏi lịch đăng)' : ''}.`
} }];
